7	});
8	
9	export { AI_MODEL_HEAVY, AI_MODEL_LIGHT };
10	
11	// Helper: call AI with streaming and parse JSON response
12	// ClipProxy returns content:null in non-streaming mode, so we use streaming
13	export async function callAiJson<T>(
14	  prompt: string,
15	  systemPrompt: string,
16	  model: string = AI_MODEL_HEAVY,
17	  fallback: T
18	): Promise<T> {
19	  try {
20	    const stream = await ai.chat.completions.create({
21	      model,
22	      messages: [
23	        { role: 'system', content: systemPrompt },
24	        { role: 'user', content: prompt },
25	      ],
26	      stream: true,
27	      temperature: 0.1,
28	      max_tokens: 16000,
29	    });
30	
31	    let content = '';
32	    for await (const chunk of stream) {
33	      const delta = chunk.choices[0]?.delta?.content;
34	      if (delta) content += delta;
35	    }
36	
37	    console.log(`[AI] model=${model} content_length=${content.length}`);
38	
39	    // Strip markdown fences if present
40	    const cleaned = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/,'').trim();
41	    if (!cleaned) {
42	      console.error('[AI] Empty response after streaming');
43	      return fallback;
44	    }
45	    return JSON.parse(cleaned) as T;
46	  } catch (err) {
47	    console.error('AI JSON call failed:', err);
48	    return fallback;
49	  }
50	}
51	
52	// Helper: call AI with streaming and get plain text response
53	export async function callAiText(
54	  prompt: string,
55	  systemPrompt: string,
56	  model: string = AI_MODEL_LIGHT
57	): Promise<string> {
58	  try {
59	    const stream = await ai.chat.completions.create({
60	      model,
61	      messages: [
62	        { role: 'system', content: systemPrompt },
63	        { role: 'user', content: prompt },
64	      ],
65	      stream: true,
66	      temperature: 0.3,
67	    });
68	
69	    let content = '';
70	    for await (const chunk of stream) {
71	      const delta = chunk.choices[0]?.delta?.content;
72	      if (delta) content += delta;
73	    }
74	
75	    return content;
76	  } catch (err) {
77	    console.error('AI text call failed:', err);
78	    return '';
79	  }
80	}
